create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.BESCH_FAKTURA_DET_2 cluster by (dat_faktura)(
	FAKTURA_BELEG_ID NUMBER(18,0) NOT NULL COMMENT 'Das Feld enthält die Beleg ID der Faktura und dient der eindeutigen Identifikation der Fakturabelege.',
	FAKTURA_BELEG_POS_ID NUMBER(38,0) NOT NULL COMMENT 'Das Feld enthält die Nummer einer Fakturaposition und dient zusammen mit der Fakturabeleg ID  der eindeutigen Identifikation der Fakturabelegpositionen.',
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Der Mandant_2 1 steht im DWH für Deutschland (der Wert 222 aus dem SAP System für Deutschland wird in Wert 1 umgewandelt).',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel_2 - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel_2 -> Counter +1',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Die Wup_id entspricht der Nummer des Werks/Betriebs. Dabei kann es sich entweder um ein Verteilzentrum, ein Lager oder einen Markt handeln. Zusammen mit der nb_id kann ein Eintrag aus der DWH Tabelle wup_2 eindeutig identifiziert werden. SAP RET - VBPA - KUNNR',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Die nb_id identifiziert die Nebenbetriebe (z.B. Tankstelle, Backshop, usw.) für einen Betrieb/Werk (= wup_id).',
	LAGERORT_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Dieses Feld referenziert die DWH Tabelle Lagerort.\n            \n            ',
	VERRECHNUNG_BETRAG NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Verrechnungswert einer Position in einem lieferbezogenen Fakturabeleg. Der Verrechnungswert wird bei der Buchung des Warenausgangs ermittelt. Aus wavwr',
	ZWSUM_1_BETRAG NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Konditionszwischensumme 1 aus dem Kalkulationsschema. Dies entspricht dem End Betrag des Schemas.',
	ZWSUM_2_BETRAG NUMBER(18,4) COMMENT 'Konditionszwischensumme 2 aus dem Kalkulationsschema. Dies entspricht dem Verkaufspreis.',
	ZWSUM_3_BETRAG NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Konditionszwischensumme 3 aus dem Kalkulationsschema. Dies entspricht dem Einkaufspreis Netto bei Reklamationen (Einkaufspreis netto  bzw. EK-Aktion_2 netto vermindert um die Reklapauschale).',
	ZWSUM_4_BETRAG NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Konditionszwischensumme 4 aus dem Kalkulationsschema. Dies entspricht dem Lagerwert bei Reklamationen (Reklapauschale)',
	ZWSUM_5_BETRAG NUMBER(18,4) COMMENT 'Konditionszwischensumme 5 aus dem Kalkulationsschema. Dies entspricht dem Verkaufswert bei Reklamationen.',
	ZWSUM_6_BETRAG NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Konditionszwischensumme 6 aus dem Kalkulationsschema. Dies entspricht dem Wert der Logistikvergütung für diese Position.',
	MENGE_FAKTURA_BME NUMBER(18,3) NOT NULL COMMENT 'Fakturierte Menge der Fakturabelegposition.',
	AKTION_ID VARCHAR(10) COLLATE 'en-ci' COMMENT 'Nummer zur Identifizierung einer Aktion_2, für die beschafft werden soll. Sie können pro Position eines Einkaufsbelegs eingeben, zu welcher Aktion_2 die Position gehört.',
	VERK_MENGE_EINH_ID VARCHAR(3) NOT NULL COMMENT 'Dieses Feld enthält die Mengenheiheit für die Berechnung der Basismenge in die alternative Mengeneinheit (Verkaufsmenge). Dazu ist der Umrechnungsfaktor aus der DWH Tabelle art_umrechnung_faktor_per_2 pro Material zu ermitteln.',
	MENGE_FAKTURA_KOLLI NUMBER(18,3) NOT NULL COMMENT 'Dieses Feld enthält die Menge in der Kollimengeneinheit. Der gültige Umrechnungsfaktor wird aus der DWH Tabelle art_umrechnung_faktor_per_2 ermittelt.',
	MENGE_FAKTURA_PALETTE NUMBER(18,3) COMMENT 'Dieses Feld enthält die Menge in der Palettenmengeneinheit. Der erforderliche Umrechnungsfaktor wird aus den DWH Tabellen art_vorschlagswert_per_2 und art_umrechnung_faktor_per_2 ermittelt.',
	DAT_LEIST_ERSTELLUNG DATE NOT NULL COMMENT 'Datum der Leistungserstellung.     \n            ',
	VORLAGE_BELEG_ID NUMBER(18,0) NOT NULL COMMENT 'Belegnummer des Vorlagebeleges',
	VORLAGE_BELEG_POS_ID NUMBER(38,0) NOT NULL COMMENT 'Positionsnummer des Vorlagebelegs',
	BEST_BELEG_ID NUMBER(18,0) NOT NULL COMMENT 'Das Feld enthält die Beleg ID der Bestellung und dient der eindeutigen Identifikation der Bestellbelege.\n            (Dieses Feld hat momentan keine Werte, zukünftig soll dies die Referenz zu der Bestellung ermöglichen)',
	BEST_BELEG_POS_ID NUMBER(38,0) NOT NULL COMMENT 'Das Feld enthält die Nummer einer Bestellposition und dient zusammen mit der Bestellbelet ID  der eindeutigen Identifikation der Bestellbelegpositionen.\n            (Dieses Feld hat momentan keine Werte, zukünftig soll dies die Referenz zu der Bestellung ermöglichen',
	DAT_FAKTURA_SAP DATE NOT NULL COMMENT 'Das Original - Fakturadatum aus SAP. Gehört logisch nur in die Kopftabelle und ist aus historischen Gründen hier gespeichert',
	AUFTRAG_GRUND_ID VARCHAR(3) COLLATE 'en-ci' COMMENT 'Dieses Attribut gibt den Grund für die Erstellung des Verkaufsbelegs an. Referenz zu der Tabelle l_auftrag_grund_2',
	DAT_FAKTURA DATE NOT NULL COMMENT 'Abhängig von der Fakturaart ist hier entweder das Fakturadatum oder das Datum der Leistungserstellung hinterlegt Das Feld wird aus der Kopftabelle \""vererbt\"", um einen PPI darüber bilden zu können (Performance!)',
	ZWSUM_8_BETRAG NUMBER(18,4) COMMENT 'Enthält den Rabattbetrag  bezogen auf den VK_2 im Fall von teilkostenloser Lieferung.',
	ZWSUM_9_BETRAG NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Enthält den Rabattbetrag - bezogen auf den EK - im Fall von teilkostenloser Lieferung. Format decimal(18,2) Compress CD-47-AD-36-C7-B7-B2-2A-FF-C7-61-09-CC-15-E3-DD',
	BESTELLART_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Die Bestellart wurde in diese Tabelle einbezogen, um teilkostenlose Lieferungen aus den Fakturen bestimmen zu können. Eigenstlich gehört die Bestellart zu den Bestellungen (besch_best_2)',
	MENGE_FAKTURA_KG NUMBER(18,3) COMMENT 'Die fakturierte Mengen in Kilogramm. Entspricht bei Gewichtsware der Column menge_fakturiert, wird bei Stückware berechnet. Redundantes Feld aus Performancegründen für einen! Bericht Fakturaliste Wurst',
	DAT_PREISFINDUNG DATE COMMENT 'Datum für Preisfindung und Währungskurs, kann vom Fakturadatum abweichen',
	MWST NUMBER(9,2) COMMENT 'Mehrwertsteuersatz. Wird aus Performancegründen hier redundant gespeichert. Datenformat mit Absicht abweichend von der Tabelle mwst',
	EK_NETTO_BNK NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Einkaufspreis netto plus Bezugsnebenkosten. Enthält den Aktionspreis, wenn vorhanden, sonst den Normalpreis.',
	EK_MEP NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'Markteinstandspreis (Bedeutung vgl. Kalkulationsschema).',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	BETRAG_EK_MEP_VOR_FWU NUMBER(38,5) WITH MASKING POLICY #unknown_policy COMMENT 'Menge * Markteinstandspreis ohne Logistikkosten inkl. Handlingkosten. Quellfeld: ZEKP.MEPOL.',
	BETRAG_LOGKOSTENZUSCHLAG NUMBER(38,5) WITH MASKING POLICY #unknown_policy COMMENT 'Menge * Logistikkostenzuschlag (ZEKP.LOKAU).',
	constraint PK_BESCH_FAKTURA_DET primary key (MANDANT_ID, FAKTURA_BELEG_ID, FAKTURA_BELEG_POS_ID)
)COMMENT='TP408_LVS - In dieser Tabelle sind die Fakturabelegpositionen aus der SAP Tabelle VBRP enhalten  nur für Mandant_2 1. Die dazugehörigen Kopfinformationen befinden sich in der DWH Tabelle FAKTURA.'
;
